/**
 * The real answers of the real API (generated by `scripts/app/gen_contract.py`, checked by
 * `tests/server/test_app_contract.py`). The app's tests read these and nothing hand-written.
 */
import approvalsFile from "./contract/approvals.json";
import demoFile from "./contract/demo.json";
import modelsFile from "./contract/models.json";
import soloFile from "./contract/solo.json";
import stopFile from "./contract/stop.json";
import tamperFile from "./contract/tamper.json";
import windowsFile from "./contract/windows.json";

import type {
  RawApproval,
  RawBudget,
  RawLedgerPage,
  RawRunDetail,
  RawRunList,
  RawVerify,
} from "@/api/server/raw";

interface Recorded<T> {
  status: number;
  body: T;
}

const files = { demo: demoFile, tamper: tamperFile, windows: windowsFile, stop: stopFile, approvals: approvalsFile, models: modelsFile, solo: soloFile } as unknown as Record<
  string,
  Record<string, Recorded<unknown>>
>;

/** One recorded answer: `answer<RawRunDetail>("demo", "run_done")`. Fails loudly if it isn't there. */
 
export function answer<T>(file: keyof typeof files, name: string): Recorded<T> {
  const found = files[file]?.[name];
  if (found === undefined) throw new Error(`no recorded answer ${file}.${name}: regenerate with scripts/app/gen_contract.py`);
  return found as Recorded<T>;
}

// eslint-disable-next-line @typescript-eslint/no-unnecessary-type-parameters -- the caller states the shape it expects
export const body = <T>(file: keyof typeof files, name: string): T => answer<T>(file, name).body;

export const rawDone = body<RawRunDetail>("demo", "run_done");
export const rawNeedsHuman = body<RawRunDetail>("demo", "run_needs_human");
export const rawRunList = body<RawRunList>("demo", "runs");
export const rawLedger = body<RawLedgerPage>("demo", "run_needs_human_ledger");
export const rawVerifyAnchored = body<RawVerify>("demo", "verify_all");
export const rawVerifyNoAnchors = body<RawVerify>("demo", "noanchors_verify_all");
export const rawBudgets = body<RawBudget[]>("demo", "budgets");
export const rawApprovals = body<RawApproval[]>("approvals", "list");
